insert into fests (id, org_id, name, slug, tagline, description, start_date, end_date, venue, art_seed) values
('c0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001', 'AXON Tech Carnival 2026', 'axon-tech-carnival-2026', 'Four days of robots, code and controlled chaos.', 'The club''s flagship festival. Eight competitive events and workshops spanning autonomous robotics, drone piloting, machine vision and esports, hosted across the college campus. Open to school and university students nationwide.', '2026-10-03', '2026-10-17', 'Main Campus, Dhaka Residential Model College', 11),
('c0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000001', 'RoboSprint Winter 2026', 'robosprint-winter-2026', 'Build something that moves in 48 hours.', 'A winter build sprint focused on making rather than competing. Teams arrive with an idea and leave with a working prototype, supported by mentor hours, a stocked component library and a lot of coffee.', '2026-12-12', '2026-12-14', 'AXON Lab & Innovation Hall', 23),
('c0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000001', 'Freshers'' Circuit 2027', 'freshers-circuit-2027', 'Your first robot starts here.', 'An onboarding festival for students who have never picked up a soldering iron. Every session is beginner-first, free to attend, and ends with something you built yourself and get to keep.', '2027-02-20', '2027-02-22', 'AXON Lab, Academic Building 2', 37),
('c0000000-0000-4000-8000-000000000004', 'a0000000-0000-4000-8000-000000000001', 'AXON Tech Carnival 2025', 'axon-tech-carnival-2025', 'The one that started it all.', 'The club''s first festival, archived here for reference. Results and registration records are preserved so members can look back at past editions.', '2025-09-18', '2025-09-20', 'Main Campus, Dhaka Residential Model College', 5);
